export function Toggle({ on, onChange }) {
  return (
    <button
      type="button"
      onClick={() => onChange(!on)}
      className={`relative w-11 h-6 rounded-full transition-colors flex-shrink-0 ${on ? "bg-navy" : "bg-gray-200"}`}
      aria-pressed={on}
    >
      <span
        className={`absolute top-1 w-4 h-4 bg-white rounded-full shadow transition-transform ${on ? "translate-x-6" : "translate-x-1"}`}
      />
    </button>
  );
}

export function Tag({ children, variant = "default" }) {
  const styles = {
    default: "bg-gray-100 text-gray-600",
    remote: "bg-blue-50 text-blue-700",
    new: "bg-purple-50 text-purple-700",
    presential: "bg-teal-50 text-teal-700",
    skill: "bg-purple-50 text-purple-700",
    warning: "bg-amber-50 text-amber-800",
    success: "bg-blue-50 text-blue-700",
  };
  return (
    <span className={`text-xs px-2.5 py-1 rounded-full font-medium ${styles[variant] || styles.default}`}>
      {children}
    </span>
  );
}

export function Modal({ open, onClose, children, className = "max-w-lg" }) {
  if (!open) return null;
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={onClose} />
      <div className={`relative bg-white rounded-2xl shadow-xl w-full ${className}`}>{children}</div>
    </div>
  );
}

export function Field({ label, children, className = "" }) {
  return (
    <div className={`flex flex-col gap-1.5 ${className}`}>
      {label && <label className="text-sm font-medium text-gray-700">{label}</label>}
      {children}
    </div>
  );
}

export const inputClass =
  "w-full px-4 py-3 rounded-xl bg-gray-50 border border-transparent text-sm outline-none focus:border-navy focus:bg-white transition-colors";
